import {monthLabel,dateLabel,rangeLabel} from './display-dates.js';
import {buildReport} from './reports-model.js';
import {monthlyGoal} from './business-read.js';
export function createReportsUI(env,workspace){
  const {state,esc,money,btn,icon,go,render,doc,formData,notify}=env;
  const options=()=>({period:state.reportPeriod,month:state.reportMonth,from:state.reportFrom,to:state.reportTo});
  const val=v=>esc(v??'');
  const rows=items=>`<dl class="workflow-summary">${items.map(([t,v])=>`<div><dt>${t}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
  const exactMoney=money;
  function body(r,expanded=false){
    const details=(title,html)=>`<details class="workflow-disclosure report-disclosure" ${expanded?'open':''}><summary>${title}</summary><div>${html}</div></details>`;
    return `<section class="report-hero"><span>${r.range.label}</span><h2 class="num">${money(r.sold)}</h2><p>Vendido · ${r.sales} ${r.sales===1?'venta':'ventas'} · ${r.units} unidades</p><small>${rangeLabel(r.range.from,r.range.to)}</small></section>
    <section class="report-block"><h2>Ventas y cobros</h2>${rows([['Cobrado en el período',money(r.money.collected)],['Fiado pendiente actual',money(r.debtPending)],['Transferencias por verificar',money(r.transferPending)]])}<p class="caption">Pendientes actuales de las ventas de estas fechas. Pueden cambiar con abonos y verificaciones posteriores.</p>${details('Cómo se compone lo cobrado',rows([['Efectivo',money(r.money.cash)],['Transferencias',money(r.money.transfer)],['Ticket promedio',r.average===null?'Sin ventas':exactMoney(r.average)]])+'<p class="caption">Incluye abonos y correcciones de dinero de estas fechas. El fiado y las transferencias por verificar no son cobros.</p>')}</section>
    <section class="report-block"><h2>Costos y ganancia</h2>${r.costComplete?`<p class="report-result"><span>Ganancia estimada de ventas</span><strong>${exactMoney(r.gross)}</strong></p><p class="caption">Ventas menos costo de lo vendido, antes de gastos.</p>`:`<p class="supplier-issue">Ganancia total pendiente: faltan costos.</p>${rows([['Unidades sin costo',r.unknownUnits],['Ganancia parcial',exactMoney(r.coveredGross)]])}<p class="caption">La ganancia parcial corresponde sólo a unidades con costo identificado.</p>${r.unresolved.map(u=>`<button class="text-btn" data-sale="${u.saleNumber}">Venta ${u.saleNumber} · ${esc(u.name)} · ${u.qty} un. sin costo${icon('chevron')}</button>`).join('')}`}${details('Detalle del costo',rows([['Unidades con costo',r.coveredUnits+' de '+r.units],['Costo identificado',exactMoney(r.costKnown)]]))}</section>
    <section class="report-block"><h2>Dinero registrado</h2>${rows([['Variación de dinero',money(r.money.net)],['Gastos pagados',money(r.money.expenses)],['Mercadería pagada',money(r.money.purchases)]])}<p class="caption">La variación no es ganancia ni saldo bancario.</p>${details('Aportes, retiros y mercadería',rows([['Aportes',money(r.money.contributions)],['Retiros',money(r.money.withdrawals)],['Mercadería recibida',money(r.received)],['Pendiente actual de esas recepciones',money(r.receiptPending)]])+'<p class="caption">Los aportes no son ventas. Los traspasos no generan ingresos.</p>')}</section>
    ${details('Productos vendidos · '+r.products.length,r.products.length?r.products.map(p=>`<div class="report-product"><span><strong>${esc(p.name)}</strong><small>${esc(p.variety+' · '+p.size)}</small></span><b>${p.qty} un.</b></div>`).join(''):'<p class="caption">Sin ventas en el período.</p>')}
    ${r.laterCorrections.length?`<section class="report-block"><h2>Cambios posteriores al período</h2><p class="caption">Incluye ${r.laterCorrections.length} correcciones posteriores a estas fechas. Los importes muestran el estado actual de esas ventas.</p>${r.laterCorrections.map(c=>`<button class="text-btn" data-correction="detail" data-id="${c.id}">${esc(c.reason)} · ${dateLabel(c.day)}${icon('chevron')}</button>`).join('')}</section>`:''}
    ${details('Correcciones registradas · '+r.corrections.length,`<p class="caption">${r.corrections.filter(c=>c.status==='applied').length} aplicadas · ${r.corrections.filter(c=>c.status==='review').length} pendientes. Los importes comerciales corresponden a la jornada original; el dinero, al día del cobro o devolución.</p>${r.corrections.map(c=>`<button class="text-btn" data-correction="detail" data-id="${c.id}">${esc(c.reason)} · ${dateLabel(c.day)}${icon('chevron')}</button>`).join('')}`)}`;
  }
  function reports(){let r;try{r=buildReport(state,options());}catch(error){return selector()+`<p class="error">${esc(error.message)}</p>`;}return `${selector()}${body(r)}${state.reportPeriod==='month'?`<section class="report-block"><h2>Meta de ventas del mes</h2>${r.goal?`<p class="report-result"><strong>${money(r.goal)}</strong><span>${Math.round(r.goalProgress*100)} % alcanzado · ${r.sold>=r.goal?'Meta alcanzada':'Faltan '+money(r.goal-r.sold)}</span></p><progress class="goal-progress" max="100" value="${Math.min(100,r.goalProgress*100)}"></progress>`:'<p class="caption">Todavía no definiste una meta para este mes.</p>'}<button class="text-btn" data-report="goal">${r.goal?'Cambiar meta':'Definir meta'}${icon('chevron')}</button><button class="btn secondary" data-report="print-view">${icon('list')}Informe mensual</button></section>`:''}`;}
  function selector(){return `<div class="report-periods" role="group" aria-label="Período del reporte">${[['today','Hoy'],['week','Semana'],['month','Mes'],['range','Fechas']].map(([k,t])=>`<button data-report="period" data-period="${k}" aria-pressed="${state.reportPeriod===k}">${t}</button>`).join('')}</div>${state.reportPeriod==='month'?`<label class="report-date">Mes<input id="report-month" type="month" value="${val(state.reportMonth)}"></label>`:state.reportPeriod==='range'?`<div class="report-range"><label>Desde<input id="report-from" type="date" value="${val(state.reportFrom)}"></label><label>Hasta<input id="report-to" type="date" value="${val(state.reportTo)}"></label></div>`:''}`;}
  function goal(){return `<p class="caption">Meta de ventas para ${monthLabel(state.reportMonth)}. El historial de cambios se conserva.</p><form id="report-goal-form" class="product-form workflow-form"><label>Meta mensual ($)<input name="amount" type="number" inputmode="numeric" min="1" step="1" value="${val(state.workspaceDraft.amount)}"></label><p class="caption">Dejá el importe vacío para quitar la meta de este mes.</p></form>`;}
  function print(){const r=buildReport(state,{period:'month',month:state.reportMonth});return `<article class="monthly-print"><header class="print-heading"><img class="mora-logo-full report-brand-dark" src="assets/brand/mora-vineria.svg" alt="Mora Vinería"><img class="mora-logo-full report-brand-light" src="assets/brand/mora-vineria-light.svg" alt="Mora Vinería"><h1>Informe mensual · ${monthLabel(state.reportMonth)}</h1><p>Registro interno · sin validez fiscal</p></header>${body(r,true)}${rows([['Meta mensual',r.goal?money(r.goal):'Sin definir'],['Avance',r.goal?Math.round(r.goalProgress*100)+' %':'—'],['Falta para la meta',r.goal?money(Math.max(0,r.goal-r.sold)):'—']])}<footer>Generado ${new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Salta',dateStyle:'long',timeStyle:'short'}).format(new Date())}. Información local de este dispositivo.</footer></article>`;}
  async function click(b){const a=b.dataset.report;if(!a)return false;if(a==='period'){state.reportPeriod=b.dataset.period;render();}if(a==='goal')workspace.start('monthly-goal',{amount:monthlyGoal(state,state.reportMonth)??''},'reportGoal',state.reportMonth);if(a==='save-goal'){const f=doc.querySelector('#report-goal-form');if(!f.reportValidity())return true;const amount=String(formData(f).get('amount')||'').trim();await workspace.run('monthly-goal',{month:state.reportMonth,amount:amount?Number(amount):null});}if(a==='print-view')go('reportPrint');if(a==='print')env.print();return true;}
  function change(e){const key={'report-month':'reportMonth','report-from':'reportFrom','report-to':'reportTo'}[e.target.id];if(key){state[key]=e.target.value;render();}if(e.target.closest?.('#report-goal-form'))state.workspaceDraft.amount=e.target.value;}
  function dock(){if(state.page==='reportGoal')return '<div class="dock"><button class="btn primary" data-report="save-goal">Guardar meta</button></div>';if(state.page==='reportPrint')return '<div class="dock"><button class="btn primary" data-report="print">Imprimir o guardar PDF</button></div>';return '';}
  return {screens:{reports,reportGoal:goal,reportPrint:print},click,change,dock,body};
}
